def fetch_preview(url, fetch, resolve=socket.gethostbyname):
    """Return fetch(url) for a public http(s) URL.

    `fetch` performs the HTTP request; `resolve` maps a host name to an IP address.
    """
    parts = urlparse(url)
    if parts.scheme not in ("http", "https") or not parts.hostname:
        raise ValueError("only http(s) URLs can be previewed")

    hostname = parts.hostname

    # Check for IPv6 loopback (::1) directly in the URL string
    if hostname.startswith('['):
        # Extract the IP from brackets like [::1]
        ip_part = hostname[1:]
        if ip_part == '::1' or (ip_part.count(':') > 0 and ip_part.split(':')[0] == 'fe80'):
            raise ValueError("URL resolves to a private or loopback address")

    # Resolve hostname to IP (returns IPv4 string)
    ip_addr = resolve(hostname)

    # Check for IPv4 private/loopback addresses
    if ip_addr.startswith(('127.', '10.', '192.168.', '172.16.', '172.17.', '172.18.', '172.19.', '172.20.', '172.21.', '172.22.', '172.23.', '172.24.', '172.25.', '172.26.', '172.27.', '172.28.', '172.29.', '172.30.', '172.31.')):
        raise ValueError("URL resolves to a private or loopback address")

    # Link-local addresses (169.254.x.x)
    if ip_addr.startswith('169.254.'):
        raise ValueError("URL resolves to a link-local address")

    return fetch(url)
